};

function devLoad(tools, prs, statuses) {
    devStub._prs = prs || {};
    devStub._status = statuses || {};
    var smAsyncMod = loadModule('js/common/smAsync.js', makeRequire({
        './common/smProvider.js': {
            createSmProvider: function () { return devStub; }
        }
