            queries.push(args.query);
            return { items: [{ number: 925, labels: [] }] };
        }
    });
    var items = srcMod.query({
        query: { type: 'issue', assignee: '{machineAuthor}' }
    }, { repoInfo: { owner: 'a', repo: 'b' } });

    assert.equal(queries.length, 0,
